import{_ as o,c as t,b as n,d as a,e,a as r,w as p,r as i,o as c}from"./app-C1IcKGP3.js";const d={};function B(y,s){const l=i("RouteLink");return c(),t("div",null,[s[7]||(s[7]=n(`<h1 id="authority-management" tabindex="-1"><a class="header-anchor" href="#authority-management"><span>Authority Management</span></a></h1><p>IoTDB provides permission management functionality to implement fine-grained access control for data and cluster systems, ensuring data and system security. This document introduces the basic concepts, user definitions, permission management, authentication logic, and functional use cases of the permission module in IoTDB&#39;s table model.</p><h2 id="_1-basic-concepts" tabindex="-1"><a class="header-anchor" href="#_1-basic-concepts"><span>1. Basic Concepts</span></a></h2><h3 id="_1-1-user" tabindex="-1"><a class="header-anchor" href="#_1-1-user"><span>1.1 User</span></a></h3><p>A <strong>user</strong> is a legitimate database user. Each user is associated with a unique username and authenticated via a password. Before accessing the database, a user must provide valid credentials (a username and password that exist in the database).</p><h3 id="_1-2-permission" tabindex="-1"><a class="header-anchor" href="#_1-2-permission"><span>1.2 Permission</span></a></h3><p>A database supports multiple operations, but not all users can perform every operation. If a user is authorized to execute a specific operation, they are said to have the <strong>permission</strong> for that operation.</p><h3 id="_1-3-role" tabindex="-1"><a class="header-anchor" href="#_1-3-role"><span>1.3 Role</span></a></h3><p>A <strong>role</strong> is a collection of permissions, identified by a unique role name. Roles typically correspond to real-world identities (e.g., &quot;traffic dispatcher&quot;), where a single identity may encompass multiple users. Users sharing the same real-world identity often require the same set of permissions, and roles abstract this grouping for unified management.</p><h3 id="_1-4-default-user-and-role" tabindex="-1"><a class="header-anchor" href="#_1-4-default-user-and-role"><span>1.4 Default User and Role</span></a></h3><p>Upon initialization, IoTDB includes a default user:</p><ul><li>​<strong>Username</strong>​: <code>root</code></li><li>​<strong>Default password</strong>​: <code>root</code></li></ul><p>The <code>root</code> user is the ​<strong>administrator</strong>​, inherently possessing all permissions. This user cannot be granted or revoked permissions and cannot be deleted. The database maintains only one administrator user. Newly created users or roles start with <strong>no permissions</strong> by default.</p><h2 id="_2-permission-list" tabindex="-1"><a class="header-anchor" href="#_2-permission-list"><span>2. Permission List</span></a></h2><p>In IoTDB&#39;s table model, there are two main types of permissions: Global Permissions and Data Permissions .</p><h3 id="_2-1-global-permissions" tabindex="-1"><a class="header-anchor" href="#_2-1-global-permissions"><span>2.1 Global Permissions</span></a></h3><p>Global permissions include user management and role management.</p><p>The following table describes the types of global permissions:</p><table><thead><tr><th>Permission Name</th><th>Description</th></tr></thead><tbody><tr><td>MANAGE_USER</td><td>- Create users <br>- Delete users <br>- Modify user passwords <br>- View user permission details <br>- List all users</td></tr><tr><td>MANAGE_ROLE</td><td>- Create roles <br>- Delete roles <br>- View role permission details <br>- Grant/revoke roles to/from users <br>- List all roles</td></tr></tbody></table><h3 id="_2-2-data-permissions" tabindex="-1"><a class="header-anchor" href="#_2-2-data-permissions"><span>2.2 Data Permissions</span></a></h3><p>Data permissions consist of permission types and permission scopes.</p><ul><li>Permission Types: <ul><li>CREATE: Permission to create resources</li><li>DROP: Permission to delete resources</li><li>ALTER: Permission to modify definitions</li><li>SELECT: Permission to query data</li><li>INSERT: Permission to insert/update data</li><li>DELETE: Permission to delete data</li></ul></li><li>Permission Scopes: <ul><li>ANY: System-wide (affects all databases and tables)</li><li>DATABASE: Database-wide (affects the specified database and its tables)</li><li>TABLE: Table-specific (affects only the specified table)</li></ul></li><li>Scope Enforcement Logic:</li></ul><p>When performing table-level operations, the system matches user permissions with data permission scopes hierarchically. Example: If a user attempts to write data to <code>DATABASE1.TABLE1</code>, the system checks for write permissions in this order: 1. <code>ANY</code> scope → 2. <code>DATABASE1</code> scope → 3. <code>DATABASE1.TABLE1</code> scope. The check stops at the first successful match or fails if no permissions are found.</p><ul><li>Permission Type-Scope-Effect Matrix</li></ul><table style="text-align:left;"><tbody><tr><th>Permission Type</th><th>Scope(Hierarchy)</th><th>Effect</th></tr><tr><td rowspan="3">CREATE</td><td>ANY</td><td>Create any table/database</td></tr><tr><td>DATABASE</td><td>Create tables in the specified database; create a database with the specified name</td></tr><tr><td>TABLE</td><td>Create a table with the specified name </td></tr><tr><td rowspan="3">DROP</td><td>ANY</td><td>Delete any table/database</td></tr><tr><td>DATABASE</td><td>Delete the specified database or its tables</td></tr><tr><td>TABLE</td><td>Delete the specified table</td></tr><tr><td rowspan="3">ALTER</td><td>ANY</td><td>Modify definitions of any table/database</td></tr><tr><td>DATABASE</td><td>Modify definitions of the specified database or its tables </td></tr><tr><td>TABLE</td><td>Modify the definition of the specified table</td></tr><tr><td rowspan="3">SELECT</td><td>ANY</td><td>Query data from any table in any database</td></tr><tr><td>DATABASE</td><td>Query data from any table in the specified database</td></tr><tr><td>TABLE</td><td>Query data from the specified table</td></tr><tr><td rowspan="3">INSERT</td><td>ANY</td><td>Insert/update data in any table</td></tr><tr><td>DATABASE</td><td>Insert/update data in any table within the specified database</td></tr><tr><td>TABLE</td><td>Insert/update data in the specified table</td></tr><tr><td rowspan="3">DELETE</td><td>ANY</td><td>Delete data from any table</td></tr><tr><td>DATABASE</td><td>Delete data from tables within the specified database</td></tr><tr><td>TABLE</td><td>Delete data from the specified table</td></tr></tbody></table><h2 id="_3-user-and-role-management" tabindex="-1"><a class="header-anchor" href="#_3-user-and-role-management"><span>3. User and Role Management</span></a></h2><ol><li>Create User (Requires <code>MANAGE_USER</code> Permission)</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> USER </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#C678DD;">PASSWORD</span><span style="color:#56B6C2;">&gt;</span><span style="color:#ABB2BF;">   </span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">CREATE</span><span style="color:#ABB2BF;"> USER user1 </span><span style="color:#98C379;">&#39;passwd&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Constraints:</p><ul><li>Username: 4-32 characters (letters, numbers, special chars: <code>!@#$%^&amp;*()_+-=</code>). Cannot duplicate the admin (<code>root</code>) username. <ul><li>If the username consists entirely of numbers or contains special characters, you need to enclose it in double quotes <code>&quot;&quot;</code> when creating it.</li></ul></li><li>Password: 4-32 characters (letters, numbers, special chars). Stored as SHA-256 hash by default.</li></ul><ol start="2"><li>Modify Password</li></ol><p>Users can modify their own passwords. Modifying others&#39; passwords requires <code>MANAGE_USER</code>.</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">ALTER</span><span style="color:#C678DD;"> USER</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SET</span><span style="color:#C678DD;"> PASSWORD</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#C678DD;">password</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">ALTER</span><span style="color:#ABB2BF;"> USER tempuser </span><span style="color:#C678DD;">SET</span><span style="color:#C678DD;"> PASSWORD</span><span style="color:#98C379;"> &#39;newpwd&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="3"><li>Delete User (Requires <code>MANAGE_USER</code>)</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">DROP</span><span style="color:#C678DD;"> USER</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">DROP</span><span style="color:#ABB2BF;"> USER user1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>Create Role (Requires <code>MANAGE_ROLE</code>)</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> ROLE</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">ROLENAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> ROLE</span><span style="color:#ABB2BF;"> role1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Constraints:</p><ul><li>Role Name: 4-32 characters (letters, numbers, special chars). Cannot duplicate the admin role name.</li></ul><ol start="5"><li>Delete Role (Requires <code>MANAGE_ROLE</code>)</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">DROP</span><span style="color:#C678DD;"> ROLE</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">ROLENAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">DROP</span><span style="color:#C678DD;"> ROLE</span><span style="color:#ABB2BF;"> role1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="6"><li>Assign Role to User (Requires <code>MANAGE_ROLE</code>)</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">GRANT</span><span style="color:#C678DD;"> ROLE</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">ROLENAME</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> TO</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">GRANT</span><span style="color:#C678DD;"> ROLE</span><span style="color:#C678DD;"> admin</span><span style="color:#C678DD;"> TO</span><span style="color:#ABB2BF;"> user1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="7"><li>Revoke Role from User (Requires <code>MANAGE_ROLE</code>)</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">REVOKE</span><span style="color:#C678DD;"> ROLE</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">ROLENAME</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> FROM</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">REVOKE</span><span style="color:#C678DD;"> ROLE</span><span style="color:#C678DD;"> admin</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> user1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="8"><li>List All Users (Requires <code>MANAGE_USER</code>)</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">LIST USER</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="9"><li>List All Roles (Requires <code>MANAGE_ROLE</code>)</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">LIST </span><span style="color:#C678DD;">ROLE</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol start="10"><li>List Users in a Role (Requires <code>MANAGE_USER</code>)</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">LIST USER OF </span><span style="color:#C678DD;">ROLE</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">ROLENAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: LIST USER OF </span><span style="color:#C678DD;">ROLE</span><span style="color:#ABB2BF;"> roleuser</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="11"><li>List Roles of a User</li></ol><ul><li>Users can list their own permissions.</li><li>Listing others&#39; permissions requires <code>MANAGE_USER</code>.</li></ul><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">LIST </span><span style="color:#C678DD;">ROLE</span><span style="color:#ABB2BF;"> OF USER </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: LIST </span><span style="color:#C678DD;">ROLE</span><span style="color:#ABB2BF;"> OF USER tempuser</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="12"><li>List User Permissions</li></ol><ul><li>Users can list their own permissions.</li><li>Listing others&#39; permissions requires <code>MANAGE_USER</code>.</li></ul><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">LIST PRIVILEGES OF USER </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: LIST PRIVILEGES OF USER tempuser</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="13"><li>List Role Permissions</li></ol><ul><li>Users can list permissions of roles they have.</li><li>Listing other roles&#39; permissions requires <code>MANAGE_ROLE</code>.</li></ul><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">LIST PRIVILEGES OF </span><span style="color:#C678DD;">ROLE</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">ROLENAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: LIST PRIVILEGES OF </span><span style="color:#C678DD;">ROLE</span><span style="color:#ABB2BF;"> actor</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-permission-management" tabindex="-1"><a class="header-anchor" href="#_4-permission-management"><span>4. Permission Management</span></a></h2><p>IoTDB supports granting and revoking permissions through the following three methods:</p><ul><li>Direct assignment/revocation by a super administrator</li><li>Assignment/revocation by users with the <code>GRANT OPTION</code> privilege</li><li>Assignment/revocation via roles (managed by super administrators or users with <code>MANAGE_ROLE</code> permissions)</li></ul><p>In the IoTDB Table Model, the following principles apply when granting or revoking permissions:</p><ul><li><strong>Global permissions</strong> can be granted/revoked without specifying a scope.</li><li><strong>Data permissions</strong> require specifying both the permission type and permission scope. When revoking, only the explicitly defined scope is affected, regardless of hierarchical inclusion relationships.</li><li>Preemptive permission planning is allowed—permissions can be granted for databases or tables that do not yet exist.</li><li>Repeated granting/revoking of permissions is permitted.</li><li><code>WITH GRANT OPTION</code>: Allows users to manage permissions within the granted scope. Users with this option can grant or revoke permissions for other users in the same scope.</li></ul><h3 id="_4-1-granting-permissions" tabindex="-1"><a class="header-anchor" href="#_4-1-granting-permissions"><span>4.1 Granting Permissions</span></a></h3><ol><li>Grant a user the permission to manage users</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">GRANT</span><span style="color:#ABB2BF;"> MANAGE_USER </span><span style="color:#C678DD;">TO</span><span style="color:#ABB2BF;"> USER </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">GRANT</span><span style="color:#ABB2BF;"> MANAGE_USER </span><span style="color:#C678DD;">TO</span><span style="color:#ABB2BF;"> USER TEST_USER</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li>Grant a user the permission to create databases and tables within the database, and allow them to manage permissions in that scope</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">GRANT</span><span style="color:#C678DD;"> CREATE</span><span style="color:#C678DD;"> ON</span><span style="color:#C678DD;"> DATABASE</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#C678DD;">DATABASE</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> TO</span><span style="color:#ABB2BF;"> USER </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> WITH</span><span style="color:#C678DD;"> GRANT</span><span style="color:#C678DD;"> OPTION</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">GRANT</span><span style="color:#C678DD;"> CREATE</span><span style="color:#C678DD;"> ON</span><span style="color:#C678DD;"> DATABASE</span><span style="color:#ABB2BF;"> TESTDB </span><span style="color:#C678DD;">TO</span><span style="color:#ABB2BF;"> USER TEST_USER </span><span style="color:#C678DD;">WITH</span><span style="color:#C678DD;"> GRANT</span><span style="color:#C678DD;"> OPTION</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="3"><li>Grant a role the permission to query a database</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">GRANT</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> ON</span><span style="color:#C678DD;"> DATABASE</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#C678DD;">DATABASE</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;">TO</span><span style="color:#C678DD;"> ROLE</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">ROLENAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">GRANT</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> ON</span><span style="color:#C678DD;"> DATABASE</span><span style="color:#ABB2BF;"> TESTDB </span><span style="color:#C678DD;">TO</span><span style="color:#C678DD;"> ROLE</span><span style="color:#ABB2BF;"> TEST_ROLE</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>Grant a user the permission to query a table</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">GRANT</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> ON</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#C678DD;">DATABASE</span><span style="color:#56B6C2;">&gt;</span><span style="color:#ABB2BF;">.</span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">TABLENAME</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> TO</span><span style="color:#ABB2BF;"> USER </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">GRANT</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> ON</span><span style="color:#D19A66;"> TESTDB</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">TESTTABLE</span><span style="color:#C678DD;"> TO</span><span style="color:#ABB2BF;"> USER TEST_USER</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="5"><li>Grant a role the permission to query all databases and tables</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">GRANT</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> ANY </span><span style="color:#C678DD;">TO</span><span style="color:#C678DD;"> ROLE</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#ABB2BF;">ROLENAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">GRANT</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> ANY </span><span style="color:#C678DD;">TO</span><span style="color:#C678DD;"> ROLE</span><span style="color:#ABB2BF;"> TEST_ROLE</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="6"><li>ALL Syntax Sugar: ALL represents all permissions within a given scope, allowing flexible permission granting.</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">GRANT</span><span style="color:#ABB2BF;"> ALL </span><span style="color:#C678DD;">TO</span><span style="color:#ABB2BF;"> USER TESTUSER</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Grants all possible permissions to the user, including global permissions and all data permissions under ANY scope.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">GRANT</span><span style="color:#ABB2BF;"> ALL </span><span style="color:#C678DD;">ON</span><span style="color:#ABB2BF;"> ANY </span><span style="color:#C678DD;">TO</span><span style="color:#ABB2BF;"> USER TESTUSER</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Grants all data permissions under the ANY scope. After execution, the user will have all data permissions across all databases.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">GRANT</span><span style="color:#ABB2BF;"> ALL </span><span style="color:#C678DD;">ON</span><span style="color:#C678DD;"> DATABASE</span><span style="color:#ABB2BF;"> TESTDB </span><span style="color:#C678DD;">TO</span><span style="color:#ABB2BF;"> USER TESTUSER</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Grants all data permissions within the specified database. After execution, the user will have all data permissions on that database.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">GRANT</span><span style="color:#ABB2BF;"> ALL </span><span style="color:#C678DD;">ON</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> TESTTABLE </span><span style="color:#C678DD;">TO</span><span style="color:#ABB2BF;"> USER TESTUSER</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Grants all data permissions on the specified table. After execution, the user will have all data permissions on that table.</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-revoking-permissions" tabindex="-1"><a class="header-anchor" href="#_4-2-revoking-permissions"><span>4.2 Revoking Permissions</span></a></h3><ol><li>Revoke a user&#39;s permission to manage users</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">REVOKE</span><span style="color:#ABB2BF;"> MANAGE_USER </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> USER </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">REVOKE</span><span style="color:#ABB2BF;"> MANAGE_USER </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> USER TEST_USER</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="2"><li>Revoke a user&#39;s permission to create databases and tables within the database</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">REVOKE</span><span style="color:#C678DD;"> CREATE</span><span style="color:#C678DD;"> ON</span><span style="color:#C678DD;"> DATABASE</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#C678DD;">DATABASE</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> USER </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">REVOKE</span><span style="color:#C678DD;"> CREATE</span><span style="color:#C678DD;"> ON</span><span style="color:#C678DD;"> DATABASE</span><span style="color:#ABB2BF;"> TEST_DB </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> USER TEST_USER</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="3"><li>Revoke a user&#39;s permission to query a table</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">REVOKE</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> ON</span><span style="color:#56B6C2;"> &lt;</span><span style="color:#C678DD;">DATABASE</span><span style="color:#56B6C2;">&gt;</span><span style="color:#ABB2BF;">.</span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">TABLENAME</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> USER </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">REVOKE</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> ON</span><span style="color:#D19A66;"> TESTDB</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">TESTTABLE</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> USER TEST_USER</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="4"><li>Revoke a user&#39;s permission to query all databases and tables</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">REVOKE</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> ANY </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> USER </span><span style="color:#56B6C2;">&lt;</span><span style="color:#ABB2BF;">USERNAME</span><span style="color:#56B6C2;">&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">eg: </span><span style="color:#C678DD;">REVOKE</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> ON</span><span style="color:#ABB2BF;"> ANY </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> USER TEST_USER</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ol start="5"><li>ALL Syntax Sugar: ALL represents all permissions within a given scope, allowing flexible permission revocation.</li></ol><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">REVOKE</span><span style="color:#ABB2BF;"> ALL </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> USER TESTUSER</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Revokes all global permissions and all data permissions under ANY scope.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">REVOKE</span><span style="color:#ABB2BF;"> ALL </span><span style="color:#C678DD;">ON</span><span style="color:#ABB2BF;"> ANY </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> USER TESTUSER</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Revokes all data permissions under the ANY scope, without affecting DB or TABLE-level permissions.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">REVOKE</span><span style="color:#ABB2BF;"> ALL </span><span style="color:#C678DD;">ON</span><span style="color:#C678DD;"> DATABASE</span><span style="color:#ABB2BF;"> TESTDB </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> USER TESTUSER</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Revokes all data permissions on the specified database, without affecting TABLE-level permissions.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">REVOKE</span><span style="color:#ABB2BF;"> ALL </span><span style="color:#C678DD;">ON</span><span style="color:#C678DD;"> TABLE</span><span style="color:#ABB2BF;"> TESTDB </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> USER TESTUSER</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">-- Revokes all data permissions on the specified table.</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-3-viewing-user-permissions" tabindex="-1"><a class="header-anchor" href="#_4-3-viewing-user-permissions"><span>4.3 Viewing User Permissions</span></a></h3><p>Each user has an access control list that identifies all the permissions they have been granted. You can use the <code>LIST PRIVILEGES OF USER &lt;USERNAME&gt;</code> statement to view the permission information of a specific user or role. The output format is as follows:</p><table><thead><tr><th>ROLE</th><th>SCOPE</th><th>PRIVIVLEGE</th><th>WITH GRANT OPTION</th></tr></thead><tbody><tr><td></td><td>DB1.TB1</td><td>SELECT</td><td>FALSE</td></tr><tr><td></td><td></td><td>MANAGE_ROLE</td><td>TRUE</td></tr><tr><td>ROLE1</td><td>DB2.TB2</td><td>UPDATE</td><td>TRUE</td></tr><tr><td>ROLE1</td><td>DB3.*</td><td>DELETE</td><td>FALSE</td></tr><tr><td>ROLE1</td><td>*.*</td><td>UPDATE</td><td>TRUE</td></tr></tbody></table><ul><li>​<strong>ROLE column</strong>​: If empty, it indicates the user&#39;s own permissions. If not empty, it means the permission is derived from a granted role.</li><li>​<strong>SCOPE column</strong>​: Represents the permission scope of the user/role. Table-level permissions are denoted as <code>DB.TABLE</code>, database-level permissions as <code>DB.*</code>, and ANY-level permissions as <code>*.*</code>.</li><li>​<strong>PRIVILEGE column</strong>​: Lists the specific permission types.</li><li>​<strong>WITH GRANT OPTION column</strong>​: If <code>TRUE</code>, it means the user can grant their own permissions to others.</li><li>A user or role can have permissions in both the tree model and the table model, but the system will only display the permissions relevant to the currently connected model. Permissions under the other model will not be shown.</li></ul><h2 id="_5-example" tabindex="-1"><a class="header-anchor" href="#_5-example"><span>5. Example</span></a></h2>`,94)),a("p",null,[s[1]||(s[1]=e("Using the content from the ",-1)),r(l,{to:"/UserGuide/latest-Table/Reference/Sample-Data.html"},{default:p(()=>[...s[0]||(s[0]=[e("Sample Data",-1)])]),_:1}),s[2]||(s[2]=e(" as an example, the data in the two tables may belong to the ",-1)),s[3]||(s[3]=a("strong",null,"bj",-1)),s[4]||(s[4]=e(" and ",-1)),s[5]||(s[5]=a("strong",null,"sh",-1)),s[6]||(s[6]=e(" data centers, respectively. To prevent each center from accessing the other's database data, we need to implement permission isolation at the data center level.",-1))]),s[8]||(s[8]=n(`<h3 id="_5-1-creating-users" tabindex="-1"><a class="header-anchor" href="#_5-1-creating-users"><span>5.1 Creating Users</span></a></h3><p>Use <code>CREATE USER &lt;USERNAME&gt; &lt;PASSWORD&gt;</code> to create users. For example, the <strong>root</strong> user with all permissions can create two user roles for the <strong>ln</strong> and <strong>sgcc</strong> groups, named <strong>bj_write_user</strong> and ​<strong>sh_write_user</strong>​, both with the password ​<strong>write_pwd</strong>​. The SQL statements are:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> USER</span><span style="color:#61AFEF;"> bj_write_user</span><span style="color:#98C379;"> &#39;write_pwd&#39;</span></span>
<span class="line"><span style="color:#C678DD;">CREATE</span><span style="color:#C678DD;"> USER</span><span style="color:#61AFEF;"> sh_write_user</span><span style="color:#98C379;"> &#39;write_pwd&#39;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>To display the users, use the following SQL statement:</p><div class="language-plain line-numbers-mode" data-highlighter="shiki" data-ext="plain" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-plain"><span class="line"><span>LIST USER</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>The result will show the two newly created users, as follows:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|         User|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|bj_write_user|</span></span>
<span class="line"><span style="color:#ABB2BF;">|         </span><span style="color:#C678DD;">root</span><span style="color:#ABB2BF;">|</span></span>
<span class="line"><span style="color:#ABB2BF;">|sh_write_user|</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------+</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-2-granting-user-permissions" tabindex="-1"><a class="header-anchor" href="#_5-2-granting-user-permissions"><span>5.2 Granting User Permissions</span></a></h3><p>Although the two users have been created, they do not yet have any permissions and thus cannot perform database operations. For example, if the <strong>bj_write_user</strong> attempts to write data to ​<strong>table1</strong>​, the SQL statement would be:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> INSERT INTO</span><span style="color:#ABB2BF;"> table1(region, plant_id, device_id, model_id, maintenance, </span><span style="color:#C678DD;">time</span><span style="color:#ABB2BF;">, temperature, humidity, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, arrival_time) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;">   (</span><span style="color:#98C379;">&#39;北京&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;1001&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;100&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;A&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;180&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;2025-03-26 13:37:00&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">190</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, false, </span><span style="color:#98C379;">&#39;2025-03-26 13:37:34&#39;</span><span style="color:#ABB2BF;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>The system will deny the operation and display an error:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> INSERT INTO</span><span style="color:#ABB2BF;"> table1(region, plant_id, device_id, model_id, maintenance, </span><span style="color:#C678DD;">time</span><span style="color:#ABB2BF;">, temperature, humidity, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, arrival_time) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;">   (</span><span style="color:#98C379;">&#39;北京&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;1001&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;100&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;A&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;180&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;2025-03-26 13:37:00&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">190</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, false, </span><span style="color:#98C379;">&#39;2025-03-26 13:37:34&#39;</span><span style="color:#ABB2BF;">) </span></span>
<span class="line"><span style="color:#ABB2BF;">Msg: </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">jdbc</span><span style="color:#ABB2BF;">.IoTDBSQLException: </span><span style="color:#D19A66;">701</span><span style="color:#ABB2BF;">: </span><span style="color:#C678DD;">database</span><span style="color:#C678DD;"> is</span><span style="color:#C678DD;"> not</span><span style="color:#ABB2BF;"> specified</span></span>
<span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> use</span><span style="color:#ABB2BF;"> database1</span></span>
<span class="line"><span style="color:#ABB2BF;">Msg: </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">jdbc</span><span style="color:#ABB2BF;">.IoTDBSQLException: </span><span style="color:#D19A66;">803</span><span style="color:#ABB2BF;">: Access Denied: </span><span style="color:#C678DD;">DATABASE</span><span style="color:#ABB2BF;"> database1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The <strong>root</strong> user can grant <strong>bj_write_user</strong> write permissions for <strong>table1</strong> using the <code>GRANT &lt;PRIVILEGES&gt; ON &lt;DATABASE.TABLE&gt; TO USER &lt;USERNAME&gt;</code> statement, for example:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">GRANT</span><span style="color:#C678DD;"> INSERT</span><span style="color:#C678DD;"> ON</span><span style="color:#D19A66;"> database1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">table1</span><span style="color:#C678DD;"> TO</span><span style="color:#ABB2BF;"> USER bj_write_user</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>After granting permissions, <strong>bj_write_user</strong> can successfully write data:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">IoTDB</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> use</span><span style="color:#ABB2BF;"> database1</span></span>
<span class="line"><span style="color:#ABB2BF;">Msg: The </span><span style="color:#C678DD;">statement</span><span style="color:#C678DD;"> is</span><span style="color:#ABB2BF;"> executed successfully.</span></span>
<span class="line"><span style="color:#ABB2BF;">IoTDB:database1</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> INSERT INTO</span><span style="color:#ABB2BF;"> table1(region, plant_id, device_id, model_id, maintenance, </span><span style="color:#C678DD;">time</span><span style="color:#ABB2BF;">, temperature, humidity, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, arrival_time) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;">   (</span><span style="color:#98C379;">&#39;北京&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;1001&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;100&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;A&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;180&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;2025-03-26 13:37:00&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">190</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, false, </span><span style="color:#98C379;">&#39;2025-03-26 13:37:34&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">Msg: The </span><span style="color:#C678DD;">statement</span><span style="color:#C678DD;"> is</span><span style="color:#ABB2BF;"> executed successfully.</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-3-revoking-user-permissions" tabindex="-1"><a class="header-anchor" href="#_5-3-revoking-user-permissions"><span>5.3 Revoking User Permissions</span></a></h3><p>After granting permissions, the <strong>root</strong> user can revoke them using the <code>REVOKE &lt;PRIVILEGES&gt; ON &lt;DATABASE.TABLE&gt; FROM USER &lt;USERNAME&gt;</code> statement. For example:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">REVOKE</span><span style="color:#C678DD;"> INSERT</span><span style="color:#C678DD;"> ON</span><span style="color:#D19A66;"> database1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">table1</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> USER bj_write_user</span></span>
<span class="line"><span style="color:#C678DD;">REVOKE</span><span style="color:#C678DD;"> INSERT</span><span style="color:#C678DD;"> ON</span><span style="color:#D19A66;"> database1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">table2</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> USER sh_write_user</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Once permissions are revoked, <strong>bj_write_user</strong> will no longer have write access to ​<strong>table1</strong>​:</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">IoTDB:database1</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> INSERT INTO</span><span style="color:#ABB2BF;"> table1(region, plant_id, device_id, model_id, maintenance, </span><span style="color:#C678DD;">time</span><span style="color:#ABB2BF;">, temperature, humidity, </span><span style="color:#C678DD;">status</span><span style="color:#ABB2BF;">, arrival_time) </span><span style="color:#C678DD;">VALUES</span><span style="color:#ABB2BF;">   (</span><span style="color:#98C379;">&#39;北京&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;1001&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;100&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;A&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;180&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;2025-03-26 13:37:00&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">190</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, false, </span><span style="color:#98C379;">&#39;2025-03-26 13:37:34&#39;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">Msg: </span><span style="color:#D19A66;">org</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">apache</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">iotdb</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">jdbc</span><span style="color:#ABB2BF;">.IoTDBSQLException: </span><span style="color:#D19A66;">803</span><span style="color:#ABB2BF;">: Access Denied: </span><span style="color:#C678DD;">No</span><span style="color:#ABB2BF;"> permissions </span><span style="color:#C678DD;">for</span><span style="color:#ABB2BF;"> this operation, please </span><span style="color:#C678DD;">add</span><span style="color:#ABB2BF;"> privilege </span><span style="color:#C678DD;">INSERT</span><span style="color:#C678DD;"> ON</span><span style="color:#D19A66;"> database1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">table1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div>`,21))])}const m=o(d,[["render",B]]),A=JSON.parse('{"path":"/UserGuide/latest-Table/User-Manual/Authority-Management_apache.html","title":"Authority Management","lang":"en-US","frontmatter":{"description":"Authority Management IoTDB provides permission management functionality to implement fine-grained access control for data and cluster systems, ensuring data and system security....","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Authority Management\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-01-12T10:25:39.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://iotdb.apache.org/UserGuide/latest-Table/User-Manual/Authority-Management_apache.html"}],["meta",{"property":"og:site_name","content":"IoTDB Website"}],["meta",{"property":"og:title","content":"Authority Management"}],["meta",{"property":"og:description","content":"Authority Management IoTDB provides permission management functionality to implement fine-grained access control for data and cluster systems, ensuring data and system security...."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"en-US"}],["meta",{"property":"og:locale:alternate","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-01-12T10:25:39.000Z"}],["meta",{"property":"article:modified_time","content":"2026-01-12T10:25:39.000Z"}],["link",{"rel":"alternate","hreflang":"zh-cn","href":"https://iotdb.apache.org/zh/UserGuide/latest-Table/User-Manual/Authority-Management_apache.html"}]]},"git":{"createdTime":1768213539000,"updatedTime":1768213539000,"contributors":[{"name":"CritasWang","username":"CritasWang","email":"critas@outlook.com","commits":1,"url":"https://github.com/CritasWang"}]},"readingTime":{"minutes":8.31,"words":2493},"filePathRelative":"UserGuide/latest-Table/User-Manual/Authority-Management_apache.md","autoDesc":true}');export{m as comp,A as data};
